using System;
using System.Linq;
using System.Collections.Generic;
using System.Threading.Tasks;
namespace kok {internal static class PresentationToolDefinitions {
 internal static object Slide(){return CapabilitySchema.Obj(AgentRules.Props("title",AgentRules.Str("Slide subject; keep concise",120),"bullets",AgentRules.Arr("Short content lines. 2-4 per page; details in notes. metrics uses real value | label; process is ordered.",8,AgentRules.Str("Content line",200)),"layout",AgentRules.Str("Editable composition",20,new[]{"cover","content","two_columns","section","quote","comparison","process","cards","metrics"}),"notes",AgentRules.Str("Speaker notes and source citations",4000)),new[]{"title"});}
 static object Integer(int min,int max){return new Dictionary<string,object>{{"type","integer"},{"minimum",min},{"maximum",max}};}
 internal static AgentToolSpec[] Tools(){
  var theme=AgentRules.Str("editorial: warm magazine (default); paper: white business; midnight: near-black tech; violet: soft creative. Used for new/replaced slides only",20,new[]{"editorial","paper","midnight","violet"});
  var edit=CapabilitySchema.Obj(AgentRules.Props("action",AgentRules.Str("Applied sequentially; page numbers refer to the deck after earlier edits",20,new[]{"text","notes","replace_slide","insert_slide","delete_slide","move_slide"}),"page",Integer(0,100),"shape_id",AgentRules.Str("Exact shape ID returned by read_presentation; text action only",100),"old_text",AgentRules.Str("Exact unique text fragment in this shape; text action only",6000),"new_text",AgentRules.Str("Replacement text, or complete notes; empty allowed",6000),"slide",Slide(),"to",Integer(1,100)),new[]{"action","page"});
  return new[]{
   new AgentToolSpec{Requires=Need.NormalLibrary,CapabilityId="presentations.newPresentation",Name="create_presentation",Title="新建演示文稿",Write=true,Signature="create_presentation{title,theme?:editorial|paper|midnight|violet,slides:[{title,bullets?,layout?:cover|content|two_columns|section|quote|comparison|process|cards|metrics,notes?}](<=20)}",Description="PROPOSE a real editable PPTX, not slide screenshots. Use a cohesive theme (editorial by default), varied semantic layouts, short slide copy and speaker notes for detail/citations. Each requested slide counts toward the total, including a cover. Preview before user approval.",Properties=AgentRules.Props("title",AgentRules.Str("Presentation title",100),"theme",theme,"slides",AgentRules.Arr("1-20 slides in requested order",20,Slide())),Required=new[]{"title","slides"},Validate=Validate},
   new AgentToolSpec{Requires=Need.NormalLibrary,CapabilityId="presentations.readPresentation",Name="read_presentation",Title="读取幻灯片",Write=false,Signature="read_presentation{id,start_page?,max_pages?}",Description="Read exact slide text, native shape IDs, notes and geometry before editing. Bounded 1-based pages (default first 4); follow next_page. Image data is omitted. Does not render unsupported charts or animations.",Properties=AgentRules.Props("id",AgentRules.Id,"start_page",Integer(1,100),"max_pages",Integer(1,8)),Required=new[]{"id"},Validate=Validate,Read=(lib,state,call,token)=>{token.ThrowIfCancellationRequested();return Task.FromResult(lib.ReadAgentPresentation(call));}},
   new AgentToolSpec{Requires=Need.NormalLibrary,CapabilityId="presentations.newPresentation",Name="copy_presentation",Title="复制演示文稿",Write=true,Signature="copy_presentation{id,name}",Description="PROPOSE a kok-managed copy of an imported or existing PPTX. Preserves its original package. To edit imported originals, copy first and use the returned ID; never overwrite an imported original.",Properties=AgentRules.Props("id",AgentRules.Id,"name",AgentRules.Str("New deck name",100)),Required=new[]{"id","name"},Validate=Validate,Execute=(lib,state,call,token)=>lib.CopyAgentPresentation(state,call,token)},
   new AgentToolSpec{Requires=Need.NormalLibrary,CapabilityId="presentations.savePresentation",Name="edit_presentation",Title="修改演示文稿",Write=true,Signature="edit_presentation{id,theme?,edits:[{action:text|notes|replace_slide|insert_slide|delete_slide|move_slide,page,shape_id?,old_text?,new_text?,slide?,to?}](<=12)}",Description="PROPOSE targeted edits to an existing managed PPTX. Read first. text replaces one unique fragment in one exact native shape and retains other runs; notes replaces speaker notes. replace_slide redesigns only that page. insert_slide inserts AFTER page (0 before first); move_slide moves page to final to position. Operations run sequentially. Untouched parts are preserved. User approval required, conflicts rejected, undo available. Use copy_presentation first for imported originals.",Properties=AgentRules.Props("id",AgentRules.Id,"theme",theme,"edits",AgentRules.Arr("1-12 sequential edits",12,edit)),Required=new[]{"id","edits"},Validate=Validate}
  };
 }
 static void RequireText(Dictionary<string,object> row,string key,bool empty=false){object value;if(!row.TryGetValue(key,out value)||!(value is string)||!empty&&String.IsNullOrWhiteSpace((string)value))throw new FormatException("missing "+key);if(((string)value).Any(c=>Char.IsControl(c)&&c!='\n'&&c!='\r'&&c!='\t'))throw new FormatException("invalid "+key);}
 internal static void Validate(AgentAction action,Func<string,bool> exists){
  var spec=Tools().First(t=>t.Name==action.tool);try{CapabilitySchema.Check(CapabilitySchema.Obj(spec.Properties,spec.Required),Library.Json.Deserialize<Dictionary<string,object>>(Library.Json.Serialize(action.args)));}catch{throw new FormatException("Invalid presentation tool arguments");}
  if(action.tool!="create_presentation"){string id=Convert.ToString(action.args["id"]);if(!AgentJournal.ValidId(id)||!exists(id))throw new FormatException("unknown or out-of-scope file ID");}
  if(action.tool=="create_presentation"){RequireText(action.args,"title");var rows=AgentTaskState.Get<List<Dictionary<string,object>>>(action.args,"slides");if(rows.Count<1)throw new FormatException("slides must contain 1-20 slides");int page=0;foreach(var row in rows){RequireText(row,"title");AgentSlideDesign.Slide(row,++page,action.args.ContainsKey("theme")?Convert.ToString(action.args["theme"]):"editorial");}}
  if(action.tool=="copy_presentation")RequireText(action.args,"name");
  if(action.tool!="edit_presentation")return;var edits=AgentTaskState.Get<List<Dictionary<string,object>>>(action.args,"edits");if(edits.Count<1)throw new FormatException("edits must contain 1-12 changes");
  foreach(var edit in edits){string kind=Convert.ToString(edit["action"]);if(kind!="insert_slide"&&Convert.ToInt32(edit["page"])<1)throw new FormatException("page is 1-based");if(kind=="text"){RequireText(edit,"shape_id");RequireText(edit,"old_text");RequireText(edit,"new_text",true);if(Convert.ToString(edit["old_text"])==Convert.ToString(edit["new_text"]))throw new FormatException("text is unchanged");}else if(kind=="notes")RequireText(edit,"new_text",true);else if(kind=="replace_slide"||kind=="insert_slide"){if(!edit.ContainsKey("slide"))throw new FormatException("missing slide");RequireText(AgentTaskState.Get<Dictionary<string,object>>(edit,"slide"),"title");}else if(kind=="move_slide"&&!edit.ContainsKey("to"))throw new FormatException("missing to");}
 }
}}
